#include <iostream>
#include <string>

int main() {
    std::string city1;
    std::string city2;

    if (std::getline(std::cin, city1) && std::getline(std::cin, city2)) {
        std::cout << "City 1: " << city1 << "\n";
        std::cout << "City 2: " << city2 << "\n";
        std::cout << "Alphabetical order: ";
        if (city1 < city2) {
            std::cout << city1 << ", " << city2 << "\n";
        } else {
            std::cout << city2 << ", " << city1 << "\n";
        }
    }
    return 0;
}

#include <iostream>
#include <string>

int main() {
    // Fixed simulated winning string for deterministic execution
    std::string lottery = "54";
    std::string guess;

    if (std::cin >> guess) {
        std::cout << "The lottery number is " << lottery << "\n";
        if (guess == lottery) {
            std::cout << "Exact match: you win $10,000\n";
        } else if (guess.length() >= 2 && guess[1] == lottery[0] && guess[0] == lottery[1]) {
            std::cout << "Match all digits: you win $3,000\n";
        } else if (guess.length() >= 2 && (guess[0] == lottery[0] || guess[0] == lottery[1] 
                   || guess[1] == lottery[0] || guess[1] == lottery[1])) {
            std::cout << "Match one digit: you win $1,000\n";
        } else {
            std::cout << "Sorry, no match\n";
        }
    }
    return 0;
}

#include <iostream>
#include <iomanip>

int main() {
    double amount = 12618.98;
    double interestRate = 0.0013;
    double interest = amount * interestRate;

    std::cout << "Default: " << interest << "\n";
    std::cout << "Fixed with 2 decimals: " << std::fixed << std::setprecision(2) << interest << "\n";
    return 0;
}
